import { useState, KeyboardEvent } from 'react';
import { JxInputField, JxChip } from '@jinx-ui/react';

interface ArticleTagInputProps {
  value?: string[];
  defaultValue?: string[];
  onChange?: (tags: string[]) => void;
  label?: string;
  placeholder?: string;
}

export default function ArticleTagInput({
  value,
  defaultValue = [],
  onChange,
  label = 'Теги статьи',
  placeholder = 'Введите тег и нажмите Enter',
}: ArticleTagInputProps) {
  const isControlled = value !== undefined;
  const [internalTags, setInternalTags] = useState<string[]>(defaultValue);
  const tags = isControlled ? value : internalTags;
  const [draft, setDraft] = useState('');

  const updateTags = (next: string[]) => {
    if (!isControlled) {
      setInternalTags(next);
    }
    onChange?.(next);
  };

  const addTag = () => {
    const trimmed = draft.trim();
    if (!trimmed) {
      setDraft('');
      return;
    }
    if (!tags.includes(trimmed)) {
      updateTags([...tags, trimmed]);
    }
    setDraft('');
  };

  const removeTag = (tag: string) => {
    updateTags(tags.filter((item) => item !== tag));
  };

  const handleKeyDown = (event: KeyboardEvent<HTMLInputElement>) => {
    if (event.key === 'Enter') {
      event.preventDefault();
      addTag();
    } else if (event.key === 'Backspace' && draft === '' && tags.length > 0) {
      updateTags(tags.slice(0, -1));
    }
  };

  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: 'var(--jx-gap, 8px)' }}>
      <JxInputField
        label={label}
        placeholder={placeholder}
        value={draft}
        onChange={(event) => setDraft(event.target.value)}
        onKeyDown={handleKeyDown}
      />
      {tags.length > 0 && (
        <div style={{ display: 'flex', flexWrap: 'wrap', gap: 'var(--jx-gap, 8px)' }}>
          {tags.map((tag) => (
            <JxChip key={tag} removable onRemove={() => removeTag(tag)}>
              {tag}
            </JxChip>
          ))}
        </div>
      )}
    </div>
  );
}

